def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# We need F_2 through F_17 (inclusive)
fib_numbers = [fibonacci(i) for i in range(2, 18)]

print("F_2 to F_17:", fib_numbers)
